import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const g=JSON.parse('{"title":"Data Scope Engine","description":"","frontmatter":{},"headers":[],"relativePath":"permissions/data-scope.md","filePath":"permissions/data-scope.md"}'),n={name:"permissions/data-scope.md"};function s(d,e,r,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="data-scope-engine" tabindex="-1">Data Scope Engine <a class="header-anchor" href="#data-scope-engine" aria-label="Permalink to &quot;Data Scope Engine&quot;">​</a></h1><p>Answers &quot;which rows can this user see&quot;, independent of whether they&#39;re allowed to open the screen at all (that&#39;s <a href="./functional-permissions">functional-permissions.md</a>).</p><h2 id="the-org-tree" tabindex="-1">The org tree <a class="header-anchor" href="#the-org-tree" aria-label="Permalink to &quot;The org tree&quot;">​</a></h2><p><code>Modules/HR/Models/OrganizationStructure/</code>:</p><ul><li><strong><code>Entity</code></strong> — a company you actually administer (not every row in <code>companies</code> — that table also holds vendors/customers). <code>parent_entity_id</code> + a materialized <code>path</code> column (<code>&quot;/1/4/9/&quot;</code>) let <code>-&gt;descendantsAndSelf()</code> find every entity at or below one, in a single indexed <code>LIKE</code> query — never a recursive CTE, never an N+1 parent-walk.</li><li><strong><code>Branch</code></strong> — belongs to one <code>Entity</code>; at most one <code>is_main = true</code> per entity (enforced in <code>Branch::booted()</code>, not the database — MySQL has no partial unique index).</li><li><strong><code>Department</code></strong> — a <strong>group-wide catalog entry</strong> (see below), not one row per company. Same materialized-path tree pattern as <code>Entity</code>.</li><li><strong><code>JobTitle</code></strong> / <strong><code>JobGrade</code></strong> — group-wide, not per-entity. <code>JobGrade.level</code> is a single numeric ladder shared by every job title (via <code>job_title_grade</code>), so &quot;this grade or above&quot; is always evaluated within one job title&#39;s own allowed grades — a senior in one title is never compared against a senior in another.</li></ul><h3 id="departments-are-a-shared-catalog" tabindex="-1">Departments are a shared catalog <a class="header-anchor" href="#departments-are-a-shared-catalog" aria-label="Permalink to &quot;Departments are a shared catalog&quot;">​</a></h3><p><code>departments</code> has <strong>no <code>entity_id</code> column</strong>. &quot;Finance&quot; is one row, shared by every entity that uses it. Which entities/branches actually have a department active lives in the <code>department_entity</code> pivot (<code>department_id</code>, <code>entity_id</code>, <code>branch_id</code> nullable — null means the whole entity). This is deliberate: attaching a department to entity data-scope isolation come from different places, and conflating them is the mistake this shape avoids — see <a href="./testing">&quot;a finance manager in a child entity does not gain scope over the parent, even sharing the same department catalog entry&quot;</a> for the test that proves it.</p><h2 id="the-pivotal-record-employee" tabindex="-1">The pivotal record: <code>Employee</code> <a class="header-anchor" href="#the-pivotal-record-employee" aria-label="Permalink to &quot;The pivotal record: `Employee`&quot;">​</a></h2><p><code>Modules\\HR\\Models\\EmployeeManagement\\Employee</code> is the <strong>only</strong> bridge between a logged-in <code>User</code> and the org structure:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>employees: person_id, user_id (nullable), entity_id, branch_id, department_id,</span></span>\n<span class="line"><span>           job_title_id, job_grade_id, entity_scope, department_scope, status, ...</span></span></code></pre></div><p><code>user_id</code> is nullable — not every employee logs in (e.g. a factory worker). A <code>User</code> with no active (<code>status = &#39;active&#39;</code>) <code>Employee</code> row resolves to <strong>deny-all</strong>, everywhere, by design — this is not a bug to patch around with a fallback.</p><h2 id="two-independent-scope-dimensions" tabindex="-1">Two independent scope dimensions <a class="header-anchor" href="#two-independent-scope-dimensions" aria-label="Permalink to &quot;Two independent scope dimensions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column</th><th>Values</th><th>Answers</th></tr></thead><tbody><tr><td><code>entity_scope</code></td><td><code>own</code> | <code>branch</code> | <code>entity</code> | <code>entity_tree</code></td><td>Which companies/branches (horizontal)</td></tr><tr><td><code>department_scope</code></td><td><code>own</code> | <code>department</code> | <code>department_tree</code> | <code>all</code></td><td>Which slice of the org chart (vertical)</td></tr></tbody></table><p>Visible rows = the <strong>intersection</strong> of both, never a union. This is what lets one mechanism express every case discussed while designing this system:</p><ul><li>A group-level finance manager (<code>entity_tree</code> + <code>department_tree</code>) sees Finance across the parent entity and every descendant.</li><li>The same manager, stationed at one child entity instead (<code>entity</code> + <code>department_tree</code>), sees Finance in that one company only — never the parent, never siblings.</li><li>An employee on a non-main branch (<code>branch</code>) is confined to that branch, even for other records in the very same entity.</li><li><code>own</code> is <strong>not</strong> &quot;their branch&quot; — it&#39;s zero entity/branch broadening at all. Self-service scoping (an employee seeing their own leave requests) is a different dimension entirely (filtering by <code>employee_id</code>), never conflated with <code>branch</code>.</li></ul><p><code>department_scope = department_tree</code> walks the department&#39;s own materialized path — entity- agnostic, unaffected by which entities share that department row.</p><h2 id="organizationscoperesolver" tabindex="-1"><code>OrganizationScopeResolver</code> <a class="header-anchor" href="#organizationscoperesolver" aria-label="Permalink to &quot;`OrganizationScopeResolver`&quot;">​</a></h2><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$scope </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">OrganizationScopeResolver</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">resolve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($user); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// OrganizationScope</span></span></code></pre></div><p>Returns an <code>OrganizationScope</code> value object: <code>entityIds</code>, <code>branchIds</code>, <code>departmentIds</code>, each either <code>array&lt;int&gt;</code> (a concrete allow-list) or <code>null</code> (<strong>unrestricted</strong> — reserved for <code>super_admin</code>). An <strong>empty array</strong> (<code>[]</code>) means deny-all — the distinction between <code>null</code> and <code>[]</code> is the entire authorization boundary; never collapse it.</p><p>Resolution order:</p><ol><li><code>super_admin</code> role → <code>OrganizationScope::unrestricted()</code>, no further lookup.</li><li>No active <code>Employee</code> row for this user → <code>OrganizationScope::denyAll()</code>.</li><li>Otherwise, resolve <code>entity_scope</code> → <code>[entityIds, branchIds]</code> and <code>department_scope</code> → <code>departmentIds</code> independently, per the table above.</li></ol><p><code>explain(User $user): array{scope, trace}</code> runs the same resolution <strong>uncached</strong>, annotated with the reasoning at each step — the tool for &quot;why can&#39;t this user see that record&quot;, not for the request hot path.</p><h3 id="caching-invalidation" tabindex="-1">Caching &amp; invalidation <a class="header-anchor" href="#caching-invalidation" aria-label="Permalink to &quot;Caching &amp; invalidation&quot;">​</a></h3><p><code>resolve()</code> is cached under <code>org_scope:{user_id}:v{version}</code>, <code>rememberForever</code>. <code>OrganizationVersion</code> is a single global counter — bumping it once (via <code>Entity</code>, <code>Branch</code>, <code>Department</code>, or <code>Employee</code>&#39;s <code>saved</code>/<code>deleted</code> hooks) logically invalidates <strong>every</strong> user&#39;s cached scope at the same instant, rather than hunting down which users a tree edit affected. Reads with no intervening write never bump the counter (see <code>testing.md</code> for the anti-thrash test) — <code>rememberForever</code> genuinely never re-queries until something actually changed.</p><h2 id="scopedtoorganization-—-the-integration-point" tabindex="-1"><code>ScopedToOrganization</code> — the integration point <a class="header-anchor" href="#scopedtoorganization-—-the-integration-point" aria-label="Permalink to &quot;`ScopedToOrganization` — the integration point&quot;">​</a></h2><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> App\\Models\\Concerns\\ScopedToOrganization</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Invoice</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> extends</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Model</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ScopedToOrganization</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>That&#39;s the entire integration for any model, in any module. The trait adds a global scope (<code>App\\Support\\Organization\\OrganizationScopeConstraint</code>) that inspects which of <code>entity_id</code>/<code>branch_id</code>/<code>department_id</code> the model&#39;s table actually has (cached per-table column listing, not re-queried every row) and filters by the intersection above — a model with only <code>entity_id</code> is untouched by the department dimension, and vice versa.</p><p>No authenticated user (a queue worker, a console command, a scheduled job) → the constraint fails closed (<code>whereRaw(&#39;1 = 0&#39;)</code>). Legitimate system-wide access must opt out explicitly:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Employee</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">withoutGlobalScope</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">OrganizationScopeConstraint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;...</span></span></code></pre></div><p><code>OrganizationScopeResolver</code> itself does exactly this internally when looking up the <em>current</em> user&#39;s own <code>Employee</code> row — resolving scope must never depend on a scope that is itself being computed from that same row, or every lookup would recurse forever.</p><h2 id="known-ceilings-deliberate-not-forgotten" tabindex="-1">Known ceilings (deliberate, not forgotten) <a class="header-anchor" href="#known-ceilings-deliberate-not-forgotten" aria-label="Permalink to &quot;Known ceilings (deliberate, not forgotten)&quot;">​</a></h2><ul><li><strong>Regional/multi-branch grants</strong> beyond one <code>entity_scope</code> value — e.g. a manager over exactly 3 named branches — needs an additive <code>hr_employee_scope_grants</code> table. Not built; <code>entity_scope</code> alone covers everything currently required.</li><li><strong>Field-level visibility</strong> (e.g. hide a project&#39;s cost figure from an engineer, show it to the project manager) is not a new mechanism — it&#39;s <code>Column::visible()</code> / <code>ViewField</code> visibility callbacks the Dynamic Table/Record View engines already support, gated by the <em>functional</em> permission for that specific field&#39;s action.</li></ul>',32)])])}const u=t(n,[["render",s]]);export{g as __pageData,u as default};
